<script lang="ts">import { api } from '$lib/api';let mode='stock';let sku='';let name='';let quantity='';let locationId='';let message='';let error='';let review=false;async function save(){try{await api.post('/api/stock/items',{sku,name,category:'tools',unitOfMeasure:'piece'});message='Stock item saved.';review=false}catch(e){error=(e as Error).message}}</script><div class="page"><h1>Tools and stock intake</h1><p>Choose quantity-managed stock. Serialized items belong in Asset intake.</p><section class="panel"><label for="mode">Intake mode</label><select id="mode" bind:value={mode}><option value="stock">Quantity-managed stock</option><option value="asset">Tagged Asset (continue to Asset intake)</option></select>{#if mode==='asset'}<p>Use the normal Asset intake flow for serial numbers, tags, warranty, or individual lifecycle.</p>{:else if review}<h2>Review</h2><p>{sku} — {name} — {quantity} units at {locationId}</p><button onclick={save}>Confirm and save</button><button onclick={() => review=false}>Back</button>{:else}<label for="sku">SKU</label><input id="sku" bind:value={sku}/><label for="name">Item name</label><input id="name" bind:value={name}/><label for="quantity">Opening quantity</label><input id="quantity" type="number" min="0" step="0.001" bind:value={quantity}/><label for="location">Location ID</label><input id="location" bind:value={locationId}/><button onclick={() => review=true}>Review stock item</button>{/if}{#if error}<p role="alert">{error}</p>{/if}{#if message}<p role="status">{message}</p>{/if}</section></div><style>.page{max-width:700px;margin:auto;padding:32px}.panel{border:1px solid #ddd;border-radius:10px;padding:20px}label{display:block;margin:12px 0 5px;font-weight:600}input,select{width:100%;padding:8px}button{margin-top:16px;padding:9px}</style>
